using PactNet.Verifier;
using Xunit;

namespace CleanArch.ContractTests.Pact;

/// <summary>
/// Provider-side Pact verification — replays consumer contracts
/// against a running API. Contract files come from the pact broker
/// or the pacts/ directory generated by consumer tests.
/// </summary>
public sealed class ComputeApiPactTests
{
    private static readonly string PactDir =
        Path.Combine(AppContext.BaseDirectory, "pacts");

    [Fact]
    public void Provider_HonoursConsumerContract()
    {
        if (!Directory.Exists(PactDir)
            || !Directory.GetFiles(PactDir, "*.json").Any())
        {
            // No consumer pacts published yet — skip rather than fail.
            return;
        }

        var verifier = new PactVerifier(
            "CleanArch.ComputeApi",
            new PactVerifierConfig());

        verifier.WithHttpEndpoint(
            new Uri("http://localhost:5000"));

        foreach (var pact in Directory
            .GetFiles(PactDir, "*.json"))
        {
            verifier
                .WithFileSource(new FileInfo(pact))
                .Verify();
        }
    }
}
